import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().split()
    N = int(data[0]); M = int(data[1]); S = data[2]
    MOD = 998244353

    # group letters by match mask
    mask_count = defaultdict(int)
    for c in range(26):
        m = 0
        ch = chr(ord('a') + c)
        for j in range(N):
            if S[j] == ch:
                m |= 1 << j
        mask_count[m] += 1
    masks = list(mask_count.items())  # (mask, weight)

    size = 1 << N
    # precompute transitions: for each state, list of (weight, next_state)
    trans = []
    for state in range(size):
        row = [0] * (N + 1)
        for j in range(1, N + 1):
            row[j] = row[j - 1] + ((state >> (j - 1)) & 1)
        lst = []
        for m, w in masks:
            ns = 0
            prev = 0  # new[j-1]
            for j in range(1, N + 1):
                v = row[j]
                if prev > v:
                    v = prev
                if (m >> (j - 1)) & 1:
                    t = row[j - 1] + 1
                    if t > v:
                        v = t
                if v > prev:
                    ns |= 1 << (j - 1)
                prev = v
            lst.append((w, ns))
        trans.append(lst)

    cnt = [0] * size
    cnt[0] = 1
    for _ in range(M):
        new_cnt = [0] * size
        for state in range(size):
            c0 = cnt[state]
            if c0:
                for w, ns in trans[state]:
                    new_cnt[ns] = (new_cnt[ns] + c0 * w) % MOD
        cnt = new_cnt

    ans = [0] * (N + 1)
    for state in range(size):
        if cnt[state]:
            k = bin(state).count('1')
            ans[k] = (ans[k] + cnt[state]) % MOD
    print(' '.join(map(str, ans)))

main()

