import sys

def main():
    data = sys.stdin.read().split()
    S = data[0] if data else ""
    res = []
    for ch in S:
        if ch == 'A':
            k = 0
            while res and res[-1] == 'W':
                res.pop()
                k += 1
            res.append('A')
            if k:
                res.append('C' * k)
        else:
            res.append(ch)
    sys.stdout.write(''.join(res) + '\n')

